import java.util.*;
interface Seat {String getId();double getPrice();}
class RegularSeat implements Seat {private final String id;RegularSeat(String id){this.id=id;}public String getId(){return id;}public double getPrice(){return 150;}}
class PremiumSeat implements Seat {private final String id;PremiumSeat(String id){this.id=id;}public String getId(){return id;}public double getPrice(){return 250;}}
class ReclinerSeat implements Seat {private final String id;ReclinerSeat(String id){this.id=id;}public String getId(){return id;}public double getPrice(){return 400;}}
class Show {private final Set<String> booked=new HashSet<>();boolean available(Seat s){return !booked.contains(s.getId());}boolean reserve(Seat s){return booked.add(s.getId());}void release(Seat s){booked.remove(s.getId());}}
class Customer {final String name;Customer(String n){name=n;}}
class Booking {final Customer customer;final Show show;final List<Seat> seats;boolean cancelled;Booking(Customer c,Show s,List<Seat> x){customer=c;show=s;seats=new ArrayList<>(x);}double total(){double t=0;for(Seat s:seats)t+=s.getPrice();return t;}void cancel(){if(!cancelled){for(Seat s:seats)show.release(s);cancelled=true;}}}
public class Main {static Booking book(Customer c,Show s,List<Seat> seats){if(c==null||s==null||seats==null||seats.isEmpty()||seats.size()>6)throw new IllegalArgumentException();Set<String> seen=new HashSet<>();for(Seat x:seats)if(x==null||!seen.add(x.getId())||!s.available(x))throw new IllegalStateException("Seat "+(x==null?"null":x.getId())+" is already booked for this show.");for(Seat x:seats)s.reserve(x);return new Booking(c,s,seats);}static void cancel(Booking b,boolean started){if(started)throw new IllegalStateException("Show has started");b.cancel();}public static void main(String[]args){Show s=new Show();Customer asha=new Customer("Asha"),ravi=new Customer("Ravi"),neha=new Customer("Neha");Booking a=book(asha,s,Arrays.asList(new RegularSeat("A1"),new RegularSeat("A2"),new PremiumSeat("F5")));System.out.printf("Booking confirmed for Asha: A1, A2, F5. Total: ₹%.2f%n",a.total());try{book(ravi,s,Arrays.asList(new RegularSeat("A2")));}catch(IllegalStateException e){System.out.println("Seat A2 is already booked for this show.");}Booking r=book(ravi,s,Arrays.asList(new ReclinerSeat("R1")));System.out.printf("Booking confirmed for Ravi: R1. Total: ₹%.2f%n",r.total());cancel(a,false);System.out.println("Asha's booking cancelled. Seats A1, A2, F5 released.");Booking n=book(neha,s,Arrays.asList(new RegularSeat("A2")));System.out.printf("Booking confirmed for Neha: A2. Total: ₹%.2f%n",n.total());}}